const INK = "#151F38";
const WHITE = "#FFFFFF";

type Variant = "light" | "dark";
type Layout = "horizontal" | "stacked";

function GoldDefs({
  gradId,
  clipId,
  clipTransform,
}: {
  gradId: string;
  clipId: string;
  clipTransform?: string;
}) {
  return (
    <defs>
      <linearGradient id={gradId} x1="0" y1="1" x2="1" y2="0">
        <stop offset="0" stopColor="#C47A16" />
        <stop offset="0.45" stopColor="#E09A2E" />
        <stop offset="1" stopColor="#F6C56A" />
      </linearGradient>
      <clipPath id={clipId}>
        <path fillRule="evenodd" d={ICON} transform={clipTransform} />
      </clipPath>
    </defs>
  );
}

function IconArt({ gradId, clipId }: { gradId: string; clipId: string }) {
  return (
    <>
      <path fill={`url(#${gradId})`} fillRule="evenodd" d={ICON} />
      <g clipPath={`url(#${clipId})`}>
        <path fill="#F8D078" d="M158 14 L240 14 L240 78 L192 66 Z" />
        <path
          d="M166 22 L200 62"
          fill="none"
          stroke="#C4841C"
          strokeWidth={3}
          strokeLinecap="round"
          opacity={0.55}
        />
      </g>
    </>
  );
}

export function OrcahLogo({
  variant = "light",
  layout = "horizontal",
  className = "h-9 w-auto md:h-10",
}: {
  variant?: Variant;
  layout?: Layout;
  className?: string;
}) {
  const uid = useId().replace(/:/g, "");
  const gradId = "orcah-g" + uid;
  const clipId = "orcah-c" + uid;
  const stacked = layout === "stacked";
  const color = variant === "dark" ? WHITE : INK;
  const iconShift = stacked ? "translate(180 0)" : undefined;

  return (
    <svg
      viewBox={stacked ? "0 14 600 466" : "8 12 860 242"}
      className={className}
      role="img"
      aria-label="Orçah"
      xmlns="http://www.w3.org/2000/svg"
    >
      <title>Orçah</title>
      <GoldDefs gradId={gradId} clipId={clipId} clipTransform={iconShift} />
      <g transform={iconShift}>
        <IconArt gradId={gradId} clipId={clipId} />
      </g>
      <g transform={stacked ? "translate(-266 234)" : undefined}>
        <path fill={color} fillRule="evenodd" d={WORD} />
      </g>
    </svg>
  );
}

export function OrcahIcon({ className = "h-8 w-8" }: { className?: string }) {
  const uid = useId().replace(/:/g, "");
  const gradId = "orcah-ig" + uid;
  const clipId = "orcah-ic" + uid;
  return (
    <svg viewBox="10 14 218 238" className={className} role="img" aria-label="Orçah" xmlns="http://www.w3.org/2000/svg">
      <title>Orçah</title>
      <GoldDefs gradId={gradId} clipId={clipId} />
      <IconArt gradId={gradId} clipId={clipId} />
    </svg>
  );
}
